// Read-only summary of what JobOS's own scheduler.run_due_schedules()
// already decided and executed -- this node never re-derives
// due-ness or re-implements the concurrency guard, it only reports.
const body = $input.first().json;
const lines = (body.outcomes || []).map((o) => {
  const tag = o.error ? `FAILED: ${o.error}` : o.status;
  return `search=${o.saved_search_id} candidate=${o.candidate_id} run=${o.run_id || '-'} -> ${tag}`;
});
return [{ json: { summary: `Processed ${body.processed} due schedule(s)`, details: lines } }];
